650	    /// Emits a series of instructions to bounds check and calculate the address
651	    /// of the given WebAssembly memory.
652	    /// This function returns a register containing the requested address.
653	    ///
654	    /// In essence, when computing the heap address for a WebAssembly load or
655	    /// store instruction the objective is to ensure that such access is safe,
656	    /// but also to perform the least amount of checks, and rely on the system to
657	    /// detect illegal memory accesses where applicable.
658	    ///
659	    /// Winch follows almost the same principles as Cranelift when it comes to
660	    /// bounds checks, for a more detailed explanation refer to
661	    /// prepare_addr in wasmtime-cranelift.
662	    ///
663	    /// Winch implementation differs in that, it defaults to the general case
664	    /// for dynamic heaps rather than optimizing for doing the least amount of
665	    /// work possible at runtime, this is done to align with Winch's principle
666	    /// of doing the least amount of work possible at compile time. For static
667	    /// heaps, Winch does a bit more of work, given that some of the cases that
668	    /// are checked against, can benefit compilation times, like for example,
669	    /// detecting an out of bounds access at compile time.
670	    pub fn emit_compute_heap_address(
671	        &mut self,
672	        memarg: &MemArg,
673	        access_size: OperandSize,
674	    ) -> Result<Option<Reg>> {
675	        let ptr_size: OperandSize = self.env.ptr_type().try_into()?;
676	        let enable_spectre_mitigation = self.env.heap_access_spectre_mitigation();
677	        let add_offset_and_access_size = |offset: ImmOffset, access_size: OperandSize| {
